const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const sumJs = `'use strict';
const fs = require('fs');
const readline = require('readline');
const MOD = 1000000007n;

const rl = readline.createInterface({
  input: fs.createReadStream('data.txt'),
  crlfDelay: Infinity
});

let count = 0;
let sum = 0n;
let max = 0n;

rl.on('line', (line) => {
  const s = line.trim();
  if (s.length === 0) return;
  const v = BigInt(s);
  count++;
  sum = (sum + v) % MOD;
  if (v > max) max = v;
});

rl.on('close', () => {
  process.stdout.write(JSON.stringify({ count: count, sum: Number(sum), max: Number(max) }) + '\\n');
});
`;
fs.writeFileSync(path.join(process.cwd(), 'sum.js'), sumJs);

const out = execFileSync(process.execPath, ['--max-old-space-size=128', 'sum.js'], {
  cwd: process.cwd(),
  encoding: 'utf8',
  maxBuffer: 1 << 20
});
console.log('STDOUT:', out.trim());
const res = JSON.parse(out.trim().split('\n').pop());
if (res.count === 4000000 && typeof res.sum === 'number' && typeof res.max === 'number') {
  console.log('DONE: sum.js works under 128MB heap, count=' + res.count + ' sum=' + res.sum + ' max=' + res.max);
} else {
  console.log('FAIL: unexpected result', JSON.stringify(res));
}
